/*
 * SPDX-License-Identifier: MIT
 *
 * MaxPS4 legal textured-quad scene smoke test.
 * No Sony code, firmware, keys, SDK, or proprietary content.
 *
 * The texture itself is procedurally generated by the iOS host.
 * For ~5 seconds:
 *   - left stick moves the textured quad
 *   - right stick X rotates it
 *   - a small solid triangle is also submitted to verify mixed pipelines
 */

.section .text
.globl _start
.type _start,@function
_start:
    sub $160, %rsp
    xor %r12d, %r12d
    mov $300, %r13d

loop_frame:
    /* Controller snapshot at rsp+0, 28 bytes. */
    mov $0x4d50, %rax
    lea 0(%rsp), %rdi
    mov $28, %rsi
    syscall
    test %rax, %rax
    jne failed

    /* Begin scene at rsp+32, 20 bytes. */
    mov %r12d, 32(%rsp)
    movl $0x3b83126f, 36(%rsp)      /* clear r ~= 0.004 */
    movl $0x3ca3d70a, 40(%rsp)      /* clear g = 0.02 */
    movl $0x3df5c28f, 44(%rsp)      /* clear b = 0.12 */
    movl $0x3f800000, 48(%rsp)      /* clear a = 1.0 */

    mov $0x4d56, %rax
    lea 32(%rsp), %rdi
    mov $20, %rsi
    syscall
    test %rax, %rax
    jne failed

    /* Primitive #1: textured quad, rsp+64, 40 bytes. */
    movl $3, 64(%rsp)               /* TEXTURED_QUAD */
    mov 4(%rsp), %eax               /* left_x */
    mov %eax, 68(%rsp)
    mov 8(%rsp), %eax               /* left_y */
    mov %eax, 72(%rsp)
    movl $0x3f0ccccd, 76(%rsp)      /* width  = 0.55 */
    movl $0x3eb33333, 80(%rsp)      /* height = 0.35 */
    mov 12(%rsp), %eax              /* right_x -> rotation */
    mov %eax, 84(%rsp)
    movl $0x3f800000, 88(%rsp)      /* tint fields reserved = white */
    movl $0x3f800000, 92(%rsp)
    movl $0x3f800000, 96(%rsp)
    movl $0x3f800000, 100(%rsp)

    mov $0x4d57, %rax
    lea 64(%rsp), %rdi
    mov $40, %rsi
    syscall
    test %rax, %rax
    jne failed

    /* Primitive #2: fixed green triangle proves pipeline switching. */
    movl $2, 64(%rsp)               /* TRIANGLE */
    movl $0xbf19999a, 68(%rsp)      /* x = -0.60 */
    movl $0xbf000000, 72(%rsp)      /* y = -0.50 */
    movl $0x3e99999a, 76(%rsp)      /* width = 0.30 */
    movl $0x3e99999a, 80(%rsp)      /* height = 0.30 */
    movl $0x00000000, 84(%rsp)      /* rotation = 0 */
    movl $0x3dcccccd, 88(%rsp)      /* r = 0.10 */
    movl $0x3f800000, 92(%rsp)      /* g = 1.00 */
    movl $0x3e19999a, 96(%rsp)      /* b = 0.15 */
    movl $0x3f800000, 100(%rsp)     /* a = 1.00 */

    mov $0x4d57, %rax
    lea 64(%rsp), %rdi
    mov $40, %rsi
    syscall
    test %rax, %rax
    jne failed

    mov $0x4d58, %rax
    syscall
    test %rax, %rax
    jne failed

    mov $0x4d52, %rax
    mov $16667, %rdi
    syscall
    test %rax, %rax
    jne failed

    inc %r12d
    dec %r13d
    jnz loop_frame

    mov $4, %rax
    mov $1, %rdi
    lea ok_message(%rip), %rsi
    mov $(ok_message_end-ok_message), %rdx
    syscall

    add $160, %rsp
    mov $1, %rax
    xor %rdi, %rdi
    syscall
    ud2

failed:
    mov $4, %rax
    mov $1, %rdi
    lea fail_message(%rip), %rsi
    mov $(fail_message_end-fail_message), %rdx
    syscall
    add $160, %rsp
    mov $1, %rax
    mov $1, %rdi
    syscall
    ud2

.section .rodata
ok_message:
    .ascii "guest textured quad complete\n"
ok_message_end:
fail_message:
    .ascii "guest textured quad failed\n"
fail_message_end:
